export const TERMS = [...RICH_TERMS, ...BASIC_TERMS]

export function getTerm(id) {
  return TERMS.find((t) => t.id === id)
}

export function getTermsByCategory(categoryId) {
  return TERMS.filter((t) => t.category === categoryId)
}

